CREATE TABLE admin_action_approvals(id uuid PRIMARY KEY,requested_by uuid NOT NULL REFERENCES users(id),approved_by uuid REFERENCES users(id),action_type text NOT NULL CHECK(action_type IN ('xp_reverse','role_grant','role_revoke','role_permissions')),target_reference text NOT NULL,payload jsonb NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','executed','rejected')),requested_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',reviewed_at timestamptz,operation_id uuid UNIQUE NOT NULL,CHECK(approved_by IS NULL OR approved_by<>requested_by));
CREATE INDEX admin_approvals_queue ON admin_action_approvals(status,requested_at,id);
CREATE TABLE admin_xp_exclusions(user_id uuid REFERENCES users(id),occurrence_key text NOT NULL,original_ledger_id bigint UNIQUE REFERENCES xp_ledger(id),approval_id uuid NOT NULL REFERENCES admin_action_approvals(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,occurrence_key));
CREATE TABLE admin_achievement_states(user_id uuid REFERENCES users(id),achievement_code text REFERENCES achievement_definitions(code),reason text NOT NULL,actor_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,achievement_code));
CREATE TABLE admin_result_states(ride_id uuid PRIMARY KEY REFERENCES rides(id),state text NOT NULL CHECK(state IN ('review','invalid')),reason text NOT NULL,actor_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE privacy_requests(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('access','correction','deletion','consent','export','question')),explanation text NOT NULL,status text NOT NULL DEFAULT 'received' CHECK(status IN ('received','verifying','processing','completed','rejected')),identity_verified_by uuid REFERENCES users(id),identity_verified_at timestamptz,owner_id uuid REFERENCES users(id),resolution text,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),operation_id uuid UNIQUE NOT NULL);
CREATE INDEX privacy_request_queue ON privacy_requests(status,created_at,id);
CREATE TABLE security_incidents(id uuid PRIMARY KEY,category text NOT NULL,severity text NOT NULL CHECK(severity IN ('low','medium','high','critical')),description text NOT NULL,status text NOT NULL DEFAULT 'received' CHECK(status IN ('received','analysis','containment','correction','verification','closed')),owner_id uuid NOT NULL REFERENCES users(id),containment text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE INDEX security_incident_queue ON security_incidents(status,created_at,id);
CREATE TABLE admin_settings_versions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,settings jsonb NOT NULL,actor_id uuid REFERENCES users(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO admin_settings_versions(settings,reason) VALUES('{"reportNotice":"Em caso de risco imediato, utilize os serviços de emergência locais."}','initial_policy');
CREATE TRIGGER admin_settings_history BEFORE UPDATE OR DELETE ON admin_settings_versions FOR EACH ROW EXECUTE FUNCTION gamification_ledger_immutable();
